def f_to_c(f):
    """Fahrenheit to Celsius."""
    return (f - 32) * 9 / 5


def c_to_f(c):
    """Celsius to Fahrenheit."""
    return c * 9 / 5 + 32


def km_to_miles(km):
    return km * 0.621371

